import { gunzipSync } from "node:zlib";
import {
  AbiCoder,
  getCreateAddress,
  id,
  keccak256,
  toBeHex,
  zeroPadValue,
} from "ethers";

/**
 * Canonical EntryPoint v0.8 runtime bytecode.
 *
 * Source/deployment provenance:
 * eth-infinitism/account-abstraction v0.8.0,
 * deployments/ethereum/EntryPoint.json,
 * deployedBytecode for 0x4337084D9E255Ff0702461CF8895CE9E3b5Ff108.
 *
 * It is compressed only to keep the fixture readable and is expanded before
 * hardhat_setCode installs it at the canonical address in the local EVM.
 */
const ENTRYPOINT_V08_RUNTIME_GZIP_BASE64 =
  "";

export const ENTRYPOINT_V08_ADDRESS =
  "0x4337084D9E255Ff0702461CF8895CE9E3b5Ff108";

export const ENTRYPOINT_V08_BUILD_TEMPLATE_HASH =
  "0x518c4e21fe3b27a59a3914d37988fbb30bd892e7d86333a6ed85cf7dc093a052";

export const ENTRYPOINT_V08_BSC_TESTNET_RUNTIME_HASH =
  "0x9bb19c12079ada979da5294aa219ee5a12a2ce797272b14344e38302a2835a98";

const IMMUTABLE_OFFSETS = {
  cachedDomainSeparator: [13_585],
  cachedChainId: [13_774],
  cachedThis: [13_538],
  hashedName: [13_664],
  hashedVersion: [13_702],
  name: [6_276],
  version: [6_317],
  senderCreator: [5_838, 8_360, 20_577, 21_388],
} as const;

const ABI_CODER = AbiCoder.defaultAbiCoder();

function shortString(value: string): string {
  const encoded = Buffer.alloc(32);
  Buffer.from(value).copy(encoded);
  encoded[31] = Buffer.byteLength(value);
  return `0x${encoded.toString("hex")}`;
}

function writeImmutable(runtime: Buffer, offsets: readonly number[], value: string) {
  const bytes = Buffer.from(value.slice(2), "hex");
  if (bytes.length !== 32) throw new Error("EntryPoint immutable must be 32 bytes.");
  for (const offset of offsets) bytes.copy(runtime, offset);
}

/**
 * Links the official v0.8.0 compiler runtime template for a specific chain.
 *
 * The deployment artifact contains zero placeholders for Solidity immutables.
 * A deployed EntryPoint has chain-specific EIP-712 values plus SenderCreator
 * embedded at the compiler-declared immutable-reference offsets.
 */
export function getEntryPointV08RuntimeBytecode(chainId = 31_337n): string {
  const runtime = gunzipSync(
    Buffer.from(ENTRYPOINT_V08_RUNTIME_GZIP_BASE64, "base64"),
  );
  const hashedName = id("ERC4337");
  const hashedVersion = id("1");
  const domainTypeHash = id(
    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)",
  );
  const domainSeparator = keccak256(
    ABI_CODER.encode(
      ["bytes32", "bytes32", "bytes32", "uint256", "address"],
      [domainTypeHash, hashedName, hashedVersion, chainId, ENTRYPOINT_V08_ADDRESS],
    ),
  );
  const senderCreator = getCreateAddress({
    from: ENTRYPOINT_V08_ADDRESS,
    nonce: 1,
  });

  writeImmutable(runtime, IMMUTABLE_OFFSETS.cachedDomainSeparator, domainSeparator);
  writeImmutable(
    runtime,
    IMMUTABLE_OFFSETS.cachedChainId,
    zeroPadValue(toBeHex(chainId), 32),
  );
  writeImmutable(
    runtime,
    IMMUTABLE_OFFSETS.cachedThis,
    zeroPadValue(ENTRYPOINT_V08_ADDRESS, 32),
  );
  writeImmutable(runtime, IMMUTABLE_OFFSETS.hashedName, hashedName);
  writeImmutable(runtime, IMMUTABLE_OFFSETS.hashedVersion, hashedVersion);
  writeImmutable(runtime, IMMUTABLE_OFFSETS.name, shortString("ERC4337"));
  writeImmutable(runtime, IMMUTABLE_OFFSETS.version, shortString("1"));
  writeImmutable(
    runtime,
    IMMUTABLE_OFFSETS.senderCreator,
    zeroPadValue(senderCreator, 32),
  );

  return `0x${runtime.toString("hex")}`;
}

export function getEntryPointV08RuntimeHash(chainId = 31_337n): string {
  return keccak256(getEntryPointV08RuntimeBytecode(chainId));
}